import {useCallback, useEffect} from 'react'

import type {BuildStepList} from '../BuildStepSelector.list'

import {FocusOn} from './BuildStepSelectorList.types'

interface Props {
  focused: boolean
  loadedList: BuildStepList
  setFocus: (focusOn: FocusOn) => void
  loadNextPage: () => void
}

export function useNavigation({focused, loadedList, setFocus, loadNextPage}: Props) {
  const handleKeyDown = useCallback(
    (event: KeyboardEvent) => {
      if (!focused) {
        return
      }
      switch (event.key) {
        case 'ArrowUp':
          event.preventDefault()
          setFocus(FocusOn.PREV)
          break
        case 'ArrowDown':
          event.preventDefault()
          if (loadedList.hasFocusedLastItemInPage && !loadedList.hasReachedLastPage) {
            loadNextPage()
          }
          setFocus(FocusOn.NEXT)
          break
        case 'Escape':
          event.preventDefault()
          setFocus(FocusOn.NONE)
          break
        default:
          break
      }
    },
    [
      focused,
      loadNextPage,
      loadedList.hasFocusedLastItemInPage,
      loadedList.hasReachedLastPage,
      setFocus,
    ],
  )

  useEffect(() => {
    const findNewFocus = () => {
      if (focused) {
        return loadedList.hasFocusedItem ? undefined : FocusOn.FIRST
      } else {
        // a list should raise the event
        // of losing focus only in case of having a focused item
        // to reduce redundant events
        const shouldLoseFocus = !loadedList.isEmpty && loadedList.hasFocusedItem
        return shouldLoseFocus ? FocusOn.NONE : undefined
      }
    }

    const newFocus = findNewFocus()
    if (newFocus !== undefined) {
      setFocus(newFocus)
    }

    window.addEventListener('keydown', handleKeyDown)
    return () => window.removeEventListener('keydown', handleKeyDown)
  }, [focused, handleKeyDown, loadedList.hasFocusedItem, loadedList.isEmpty, setFocus])
}
