import Tag from '@jetbrains/ring-ui-built/components/tag/tag'
import {useRef, useState, useEffect, useCallback, useMemo} from 'react'

import styles from './RecipeTagList.module.css'

const MORE_INDICATOR_WIDTH = 60
const TAG_MARGIN = 4

interface Props {
  tags: string[]
}

export default function RecipeTagList({tags}: Props) {
  const containerRef = useRef<HTMLDivElement>(null)
  const tagsContainerRef = useRef<HTMLDivElement>(null)
  const moreRef = useRef<HTMLSpanElement>(null)
  const uniqueTags = useMemo(() => [...new Set(tags)], [tags])

  const [visibleCount, setVisibleCount] = useState<number>(uniqueTags.length)

  const calculateVisibleTags = useCallback(() => {
    if (!containerRef.current || !tagsContainerRef.current || uniqueTags.length === 0) {
      return
    }

    const tagElements = Array.from(tagsContainerRef.current.children)

    const availableWidth =
      containerRef.current.clientWidth - (uniqueTags.length > 1 ? MORE_INDICATOR_WIDTH : 0)

    // main calculation
    const {visibleTagsCount} = tagElements.reduce(
      (acc, element) => {
        const tagWidth = (element as HTMLElement).offsetWidth + TAG_MARGIN

        // if a tag is fit – continue
        if (acc.currentWidth + tagWidth <= availableWidth && !acc.limitReached) {
          return {
            currentWidth: acc.currentWidth + tagWidth,
            visibleTagsCount: acc.visibleTagsCount + 1,
            limitReached: false,
          }
        }

        // if a tag doesn't fit – mark as limit reached
        return {...acc, limitReached: true}
      },
      {currentWidth: 0, visibleTagsCount: 0, limitReached: false},
    )

    setVisibleCount(visibleTagsCount)
  }, [uniqueTags])

  // recalculate on width change
  useEffect(() => {
    calculateVisibleTags()

    const resizeObserver = new ResizeObserver(() => {
      calculateVisibleTags()
    })

    if (containerRef.current) {
      resizeObserver.observe(containerRef.current)
    }

    return () => {
      resizeObserver.disconnect()
    }
  }, [calculateVisibleTags])

  if (uniqueTags.length === 0) {
    return null
  }

  const hiddenCount = uniqueTags.length - visibleCount
  const hiddenTags = uniqueTags.slice(visibleCount).join(', ')

  return (
    <div ref={containerRef} className={styles.list}>
      <div className={styles.tagsContainer} ref={tagsContainerRef}>
        {uniqueTags.slice(0, visibleCount).map(tag => (
          <Tag key={tag} readOnly>
            <span title={tag}>{tag}</span>
          </Tag>
        ))}
      </div>
      {hiddenCount > 0 && (
        <span ref={moreRef} className={styles.more} title={hiddenTags}>
          {visibleCount === 0 ? `${hiddenCount} tags` : `+${hiddenCount} more`}
        </span>
      )}
    </div>
  )
}
