/* eslint-disable @typescript-eslint/no-magic-numbers */
export function toReadableNumber(num: number): string {
  const absNum = Math.abs(num)
  if (absNum === 0) {
    return '0'
  }

  const divisions = [
    {value: 1e9, symbol: 'B'},
    {value: 1e6, symbol: 'M'},
    {value: 1e3, symbol: 'K'},
  ]

  for (const division of divisions) {
    if (absNum >= division.value - division.value / 2000) {
      // taking rounding into account
      let result = (num / division.value).toFixed(1)
      // round to the nearest whole number if the result is close to a whole number.
      if (Math.abs(parseFloat(result) - Math.round(parseFloat(result))) < 0.05) {
        result = Math.round(parseFloat(result)).toString()
      } else if (result.endsWith('.0')) {
        result = result.slice(0, -2)
      }
      return result + division.symbol
    }
  }

  return num.toString()
}

export const normalizeProjectName = (projectName: string) =>
  projectName === '<Root project>' ? 'root' : projectName
