import {isRelativeRootUrl, resolveRelative} from '@jetbrains/teamcity-ui/dist/utils'
import {useEffect, useCallback} from 'react'

import type {GetAvailableRunnersResponse} from '../../../services/rest'

import {Slice} from './BuildStepSelector.slice'
import {Trie} from './BuildStepSelector.trie'
import type {BuildStepItemsFetcher, BuildStepItem} from './BuildStepSelector.types'
import {BuildStepType, FocusDirection} from './BuildStepSelector.types'

export const useBuildStepItemsFetcher = (
  runners: GetAvailableRunnersResponse,
): BuildStepItemsFetcher => {
  const itemsIndex = new Trie<BuildStepItem>([
    {field: 'name', tokenize: true, tokenizeCamelCase: true},
    {field: 'description', tokenize: true, tokenizeCamelCase: true},
    {field: 'tags', tokenize: true, tokenizeCamelCase: true},
  ])

  const localItems = Object.values(runners)
    .flat()
    .map(
      runner =>
        ({
          id: runner.key,
          type: runner.ownerProjectInfo ? BuildStepType.PRIVATE_RECIPE : BuildStepType.RUNNER,
          name: runner.name,
          description: runner.description,
          deprecation: runner.deprecation,
          tags: runner.tags,
          owningProject: runner.ownerProjectInfo ? runner.ownerProjectInfo.name : null,
          iconUrl: runner.iconUrl
            ? resolveRelative(
                isRelativeRootUrl(runner.iconUrl) ? runner.iconUrl : `/${runner.iconUrl}`,
              )
            : null,
          focused: false,
        }) as BuildStepItem,
    )

  localItems.forEach(item => itemsIndex.insert(item))

  const fetchItems = (
    searchQuery: string,
    type: BuildStepType,
    offset: number,
    count: number,
  ): Promise<Slice<BuildStepItem>> =>
    new Promise(resolve => {
      const filteredItems = !searchQuery
        ? itemsIndex.filter(item => item.type === type)
        : searchQuery
            .split(/\s+/)
            .map(token => itemsIndex.search(token))
            .flat()
            .filter(item => item.type === type)
            .filter((item, index, self) => index === self.findIndex(t => t.id === item.id))
      const sortedItems = filteredItems.sort(
        (a, b) => (a.deprecation ? 1 : 0) - (b.deprecation ? 1 : 0),
      ) // deprecated items go last
      const pagedItems = sortedItems.slice(offset, offset + count)
      resolve(new Slice<BuildStepItem>(pagedItems, offset, filteredItems.length))
    })

  return {
    fetch: fetchItems,
    countOf: predicate => itemsIndex.filter(predicate).length,
  }
}

interface NavigationProps {
  focus: (direction: FocusDirection, onSuccess: () => void) => void
}

const keyToFocusDirectionMap: Record<string, FocusDirection> = {
  ArrowDown: FocusDirection.DOWN,
  ArrowRight: FocusDirection.RIGHT,
  ArrowLeft: FocusDirection.LEFT,
  ArrowUp: FocusDirection.UP,
  Escape: FocusDirection.UNFOCUS,
}

export const useNavigation = ({focus}: NavigationProps) => {
  const memoizedFocus = useCallback(focus, [focus])

  const handleArrowKey = useCallback(
    (event: KeyboardEvent) => {
      const direction = keyToFocusDirectionMap[event.key]
      if (direction !== undefined) {
        memoizedFocus(direction, () => event.preventDefault())
      }
    },
    [memoizedFocus],
  )

  const handleClick = useCallback(
    (event: MouseEvent) => {
      if (event.target instanceof HTMLElement) {
        // disable focusing on the list on click
        memoizedFocus(FocusDirection.UNFOCUS, () => event.preventDefault())
      }
    },
    [memoizedFocus],
  )

  useEffect(() => {
    window.addEventListener('keydown', handleArrowKey)
    window.addEventListener('mouseup', handleClick)
    return () => {
      window.removeEventListener('keydown', handleArrowKey)
      window.removeEventListener('mouseup', handleClick)
    }
  }, [handleArrowKey, handleClick])
}
