import type * as React from 'react'
import {useCallback, useMemo, useReducer} from 'react'

import useEventCallback from '../../../hooks/useEventCallback'
import {type GetAvailableRunnersResponse, restApi} from '../../../services/rest'
import type {ProjectId} from '../../../types'

import BuildStepSearchBar from './BuildStepSearchBar/BuildStepSearchBar'
import {BuildStepSelectorDialogProvider} from './BuildStepSelector.context'
import {useBuildStepItemsFetcher, useNavigation} from './BuildStepSelector.hooks'
import PrivateRecipeList from './BuildStepSelector.list.privateRecipes'
import PublicRecipeList from './BuildStepSelector.list.publicRecipes'
import RunnerList from './BuildStepSelector.list.runners'
import {focus, initialState, reducer, search, updateFocusability} from './BuildStepSelector.reducer'
import type {FocusabilityData} from './BuildStepSelector.types'
import {BuildStepType, FocusDirection} from './BuildStepSelector.types'
import BuildStepSelectorSection from './BuildStepSelectorSection/BuildStepSelectorSection'

import styles from './BuildStepSelector.module.css'

interface Props {
  projectId: ProjectId
  runners: GetAvailableRunnersResponse
  onSelect: () => void
  onLoadingComplete: () => void
}

function BuildStepSelector({projectId, runners, onSelect, onLoadingComplete}: Props) {
  const [state, dispatch] = useReducer(reducer, initialState)
  const {searchQuery, focused} = state

  const {publicRecipesSettings} = restApi.endpoints.getPublicRecipesMode.useQuery(
    {projectId},
    {selectFromResult: ({data}) => ({publicRecipesSettings: data})},
  )
  const isPublicRecipesEnabled = publicRecipesSettings?.enabled

  const handleFormSubmit = useEventCallback((event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault()
  })

  const handleSearchChange = (query: string) => {
    const sanitizedQuery = query.trim().toLowerCase()
    if (searchQuery === sanitizedQuery) {
      return
    }
    dispatch(search(sanitizedQuery))
  }

  const handleItemActivate = useCallback(
    (itemId: string) =>
      new Promise<void>(() => {
        onSelect()
        window.BS?.selectRunnerInFlattenMode?.(itemId, onLoadingComplete)
      }),
    [onLoadingComplete, onSelect],
  )

  useNavigation({
    focus: useMemo(() => (direction, onSuccess) => dispatch(focus(direction, onSuccess)), []),
  })

  const localItemsFetcher = useBuildStepItemsFetcher(runners)

  const handleRunnersListReload = useCallback(() => {
    if (searchQuery.trim().length !== 0) {
      dispatch(focus(FocusDirection.DOWN)) // focus on the runner list
    }
  }, [searchQuery])

  const handleChangeFocusability = useCallback(
    (type: BuildStepType, focusable: FocusabilityData) => {
      dispatch(updateFocusability(type, focusable))
    },
    [],
  )

  return (
    <form onSubmit={handleFormSubmit}>
      <BuildStepSelectorDialogProvider>
        <BuildStepSearchBar
          placeholder={'Search for recipes or runners...'}
          className={styles.searchBar}
          onSearchChange={handleSearchChange}
        />
        <div className={styles.container}>
          <BuildStepSelectorSection>
            <RunnerList
              fetcher={localItemsFetcher}
              onActivate={handleItemActivate}
              searchQuery={searchQuery}
              focused={focused === BuildStepType.RUNNER}
              onReload={handleRunnersListReload}
              onFocusabilityChange={handleChangeFocusability}
            />
          </BuildStepSelectorSection>
          <BuildStepSelectorSection>
            <PrivateRecipeList
              fetcher={localItemsFetcher}
              projectId={projectId}
              onActivate={handleItemActivate}
              searchQuery={searchQuery}
              focused={focused === BuildStepType.PRIVATE_RECIPE}
              onFocusabilityChange={handleChangeFocusability}
            />
            {isPublicRecipesEnabled && (
              <PublicRecipeList
                projectId={projectId}
                onActivate={handleItemActivate}
                searchQuery={searchQuery}
                focused={focused === BuildStepType.PUBLIC_RECIPE}
                onFocusabilityChange={handleChangeFocusability}
              />
            )}
          </BuildStepSelectorSection>
        </div>
      </BuildStepSelectorDialogProvider>
    </form>
  )
}

export default BuildStepSelector
