import Button from '@jetbrains/ring-ui-built/components/button/button'
import {H4} from '@jetbrains/ring-ui-built/components/heading/heading'
import LoaderInline from '@jetbrains/ring-ui-built/components/loader-inline/loader-inline'
import Text from '@jetbrains/ring-ui-built/components/text/text'
import type {ReactNode} from 'react'
import {memo, useRef, useMemo, useEffect, useCallback, useReducer} from 'react'

import {useDebounceValue} from '../../../../hooks/useDebounceValue'
import {useBuildStepSelectorDialogContext} from '../BuildStepSelector.context'
import {BuildStepList} from '../BuildStepSelector.list'
import type {Slice} from '../BuildStepSelector.slice'
import type {BuildStepItem, BuildStepType} from '../BuildStepSelector.types'
import BuildStepSelectorItem from '../BuildStepSelectorItem/BuildStepSelectorItem'

import {useNavigation} from './BuildStepSelectorList.hooks'
import {
  reducer,
  setError,
  setFocus,
  setLoadedPage,
  setLoader,
} from './BuildStepSelectorList.reducer'
import type {FocusOn} from './BuildStepSelectorList.types'
import {LoaderType} from './BuildStepSelectorList.types'

import styles from './BuildStepSelectorList.module.css'

interface Props {
  title?: string | ReactNode
  buildStepType: BuildStepType
  fetchData: (offset: number, count: number) => Promise<Slice<BuildStepItem>>
  emptyMessage: string
  errorMessage: string
  initialEmptyMessage?: string | ReactNode
  pageSize: number
  onLengthChanged?: (itemsCount: number) => void
  onItemActivate?: (itemId: string) => Promise<void>
  onReload?: () => void
  onItemFocus?: (itemIndex: number, isVeryLastItem: boolean) => void
  reloadSignal: string
  focused: boolean
}

const DEFAULT_PAGE_SIZE = 20
const LOADER_DEBOUNCE_DELAY = 300

function BuildStepSelectorList({
  title,
  buildStepType,
  fetchData,
  emptyMessage,
  errorMessage,
  initialEmptyMessage,
  pageSize,
  onLengthChanged,
  onItemActivate,
  onReload,
  onItemFocus,
  reloadSignal,
  focused,
}: Props) {
  const [state, dispatch] = useReducer(reducer, {
    loadedList: BuildStepList.empty(buildStepType, pageSize ?? DEFAULT_PAGE_SIZE),
    loader: LoaderType.HIDDEN,
    error: null,
  })
  const {loadedList, loader, error} = state
  const debouncedLoader = useDebounceValue(loader, LOADER_DEBOUNCE_DELAY)
  const prevReloadSignal = useRef<string | undefined>(undefined)
  const dialogContext = useBuildStepSelectorDialogContext()

  const memoizedFetchData = useCallback(fetchData, [fetchData])
  const memoizedOnFocusItem = useCallback(
    (index: number) => {
      if (onItemFocus) {
        onItemFocus(index, loadedList.hasFocusedLastItem)
      }
    },
    [loadedList.hasFocusedLastItem, onItemFocus],
  )

  const memoizedOnLengthChanged = useCallback(() => {
    if (onLengthChanged) {
      onLengthChanged(loadedList.total)
    }
  }, [loadedList.total, onLengthChanged])

  const memoizedOnReload = useCallback(() => {
    if (onReload) {
      onReload()
    }
  }, [onReload])

  const loadPage = useCallback(
    (page: number, shouldReload = false) => {
      dispatch(setLoader(page === 0 ? LoaderType.FULL : LoaderType.BUTTON))
      memoizedFetchData(page * pageSize, pageSize)
        .then(fetchedItems => {
          dispatch(setLoadedPage(fetchedItems))
          memoizedOnLengthChanged()
          if (shouldReload) {
            memoizedOnReload()
          }
        })
        .catch(err => {
          dispatch(setError(err.message || 'Unknown error'))
        })
    },
    [memoizedFetchData, memoizedOnLengthChanged, pageSize, memoizedOnReload],
  )

  const loadNextPage = useCallback(() => {
    loadPage(loadedList.page + 1)
  }, [loadedList.page, loadPage])

  const focus = useCallback(
    (focusOn: FocusOn) => {
      if (dialogContext?.isOpen) {
        return
      }

      dispatch(setFocus(focusOn))
    },
    [dialogContext?.isOpen],
  )

  useEffect(() => {
    if (prevReloadSignal.current === reloadSignal) {
      return
    }
    prevReloadSignal.current = reloadSignal
    loadPage(0, true)
  }, [loadPage, reloadSignal])

  useEffect(() => {
    memoizedOnFocusItem(loadedList.focusedItemIndex)
  }, [loadedList.focusedItemIndex, memoizedOnFocusItem])

  useNavigation({
    focused,
    loadedList,
    setFocus: focus,
    loadNextPage,
  })

  const shouldShowInitialEmptyMessage = useMemo(
    () => initialEmptyMessage && loadedList.page === 1 && loadedList.isEmpty,
    [initialEmptyMessage, loadedList.isEmpty, loadedList.page],
  )

  const hasTitle = useMemo(() => title && loader !== LoaderType.HIDDEN, [title, loader])
  const isHiddenlyLoading = useMemo(() => loader === LoaderType.HIDDEN, [loader])
  const isLoadingFirstPage = useMemo(() => loader === LoaderType.FULL, [loader])
  const isDeboucedLoading = useMemo(() => debouncedLoader === LoaderType.FULL, [debouncedLoader])

  return shouldShowInitialEmptyMessage ? (
    <div className={styles.initialEmptyMessage}>{initialEmptyMessage}</div>
  ) : (
    <div className={styles.list}>
      {hasTitle && (
        <div className={styles.title}>
          <H4>{title}</H4>
        </div>
      )}
      <div>
        {error ? (
          <Text size={Text.Size.M} className={styles.errorMessage}>
            {errorMessage}
          </Text>
        ) : isHiddenlyLoading ? null : isLoadingFirstPage ? (
          isDeboucedLoading && (
            <div className={styles.loader} data-full-loader>
              <LoaderInline>{'Loading...'}</LoaderInline>
            </div>
          )
        ) : loadedList.isEmpty ? (
          <Text size={Text.Size.M} className={styles.emptyMessage}>
            {emptyMessage}
          </Text>
        ) : (
          <div data-build-step-items>
            {loadedList.mapToArrayOf(item => (
              <BuildStepSelectorItem key={item.id} {...item} activate={onItemActivate} />
            ))}
            {!loadedList.hasReachedLastPage && (
              <Button
                inline
                className={styles.nextPageButton}
                onClick={loadNextPage}
                loader={loader === LoaderType.BUTTON}
              >
                {'Show more...'}
              </Button>
            )}
          </div>
        )}
      </div>
    </div>
  )
}

export default memo(BuildStepSelectorList)
