import type {Slice} from './BuildStepSelector.slice'

export interface BuildStepItem {
  id: string
  type: BuildStepType
  name: string
  description: string
  tags?: string[]
  deprecation?: Deprecation
  owningProject?: string
  link?: string
  vendor?: Vendor
  iconUrl?: string
  downloads?: number
  rating?: number
  focused: boolean
}

export enum BuildStepType {
  RUNNER = 'RUNNER',
  PRIVATE_RECIPE = 'PRIVATE_RECIPE',
  PUBLIC_RECIPE = 'PUBLIC_RECIPE',
}

export interface Deprecation {
  type?: string
  reason?: string
  reference?: string
}

export interface Vendor {
  name: string
  verified: boolean
  link?: string
}

export interface FocusabilityData {
  isFocusInAllowed: boolean
  allowedFocusOutDirections: FocusDirection[]
}

export enum FocusDirection {
  UNFOCUS = 'UNFOCUS',
  DOWN = 'DOWN',
  UP = 'UP',
  RIGHT = 'RIGHT',
  LEFT = 'LEFT',
}

export interface BuildStepItemsFetcher {
  fetch: (
    searchQuery: string,
    type: BuildStepType,
    offset: number,
    count: number,
  ) => Promise<Slice<BuildStepItem>>
  countOf: (predicate: (item: BuildStepItem) => boolean) => number
}

interface PublicRecipeVendor {
  name: string
  url: string
  verified: boolean
}

export interface PublicRecipeSearchResult {
  name: string
  title: string
  description: string
  tags: string[]
  link: string
  icon?: string
  downloads: number
  rating: number
  vendor: PublicRecipeVendor | undefined
}

export interface PublicRecipesSearchResponse {
  recipes: PublicRecipeSearchResult[]
  totalCount: number
}

export interface PublicRecipesModeResponse {
  enabled: boolean
}

export interface PublicRecipesVersionsResponse {
  recipeName: string
  version: string
  runTypeId: string
  compatible: boolean
}

export interface PublicRecipesContentResponse extends PublicRecipesVersionsResponse {
  content: string
}
