import {trackEvent} from '../../../statistics'

const trackAnalyticsEvent = (eventName: string, data?: Record<string, string>) => {
  trackEvent({
    name: eventName,
    groupId: 'recipes.public.events.group',
    data,
  })
}

export const trackAddRecipeDialogOpened = (recipeName: string) => {
  trackAnalyticsEvent('recipes.public.ui.addRecipeDialog.opened', {
    recipeName,
  })
}

export const trackVersionListExpanded = (recipeName: string, recipeVersion: string) => {
  trackAnalyticsEvent('recipes.public.ui.addRecipeDialog.versionsExpanded', {
    recipeName,
    recipeVersion,
  })
}

export const trackSelectedVersionChanged = (recipeName: string, recipeVersion: string) => {
  trackAnalyticsEvent('recipes.public.ui.addRecipeDialog.versionChanged', {
    recipeName,
    recipeVersion,
  })
}

export const trackCopyButtonClicked = (recipeName: string, recipeVersion: string) => {
  trackAnalyticsEvent('recipes.public.ui.addRecipeDialog.copyButtonClicked', {
    recipeName,
    recipeVersion,
  })
}

export const trackRecipeAdded = (recipeName: string, recipeVersion: string) => {
  trackAnalyticsEvent('recipes.public.ui.addRecipeDialog.recipeAdded', {
    recipeName,
    recipeVersion,
  })
}

export const trackPublicRecipeLinkOpened = (
  recipeName: string,
  recipeVersion: string | undefined,
  linkLocation: RecipeLinkLocation,
) => {
  trackAnalyticsEvent('recipes.public.ui.recipeLinkOpened', {
    recipeName,
    ...(!!recipeVersion && {recipeVersion}),
    openedFrom: linkLocation,
  })
}

export const trackAllRecipesLinkOpened = () => {
  trackAnalyticsEvent('recipes.public.ui.allRecipesLinkOpened')
}

export enum RecipeLinkLocation {
  ADD_RECIPE_DIALOG = 'Add_recipe_dialog',
  ADD_BUILD_STEP_PAGE = 'Add_build_step_page',
}
