import newWindowIcon from '@jetbrains/icons/new-window-12px.svg'
import okIcon from '@jetbrains/icons/ok-12px.svg'
import starEmptyIcon from '@jetbrains/icons/star-empty-12px.svg'
import alert from '@jetbrains/ring-ui-built/components/alert-service/alert-service'
import Button from '@jetbrains/ring-ui-built/components/button/button'
import Dialog from '@jetbrains/ring-ui-built/components/dialog/dialog'
import Icon from '@jetbrains/ring-ui-built/components/icon/icon'
import {Content, Header} from '@jetbrains/ring-ui-built/components/island/island'
import {Type as ListItemType} from '@jetbrains/ring-ui-built/components/list/consts'
import LoaderInline from '@jetbrains/ring-ui-built/components/loader-inline/loader-inline'
import Panel from '@jetbrains/ring-ui-built/components/panel/panel'
import type {SelectItem} from '@jetbrains/ring-ui-built/components/select/select'
import Select, {Type} from '@jetbrains/ring-ui-built/components/select/select'
import Text from '@jetbrains/ring-ui-built/components/text/text'
import classNames from 'classnames'
import {useCallback, useEffect, useMemo, useState} from 'react'

import {emptyArray} from '../../../../utils/empty'
import CopyIconButton from '../../../common/CopyIconButton/CopyIconButton'
import Loader from '../../../common/Loader/Loader'
import useBooleanState from '../../../pages/PipelinesPages/hooks/useBooleanState'
import {
  trackAddRecipeDialogOpened,
  trackVersionListExpanded,
  trackSelectedVersionChanged,
  trackCopyButtonClicked,
  trackRecipeAdded,
  trackPublicRecipeLinkOpened,
  RecipeLinkLocation,
} from '../BuildStepSelector.analyticEvents'
import type {Vendor} from '../BuildStepSelector.types'
import {BuildStepType} from '../BuildStepSelector.types'
import BuildStepSelectorItemIcon from '../BuildStepSelectorItemIcon/BuildStepSelectorItemIcon'

import {LATEST_COMPATIBLE, truncateWithEllipsis} from './AddPublicRecipeDialog.utils'
import useRecipeEditor from './hooks/useRecipeEditor'
import {
  useApplyRecipe,
  useFetchRecipeContent,
  useFetchRecipeVersions,
} from './hooks/useRecipesContent'
import RecipeTagList from './RecipeTagList/RecipeTagList'

import styles from './AddPublicRecipeDialog.module.css'

interface Props {
  recipeId: string
  name: string
  vendor?: Vendor
  iconUrl?: string
  downloads?: number
  rating?: number
  marketplaceUrl: string
  description: string
  tags?: string[]
  onAdd: (id: string) => Promise<void>
  onClose: () => void
}

type SelectedVersionItem = SelectItem<{version: string; compatible: boolean}>
export default function AddPublicRecipeDialog({
  recipeId,
  name,
  vendor,
  iconUrl,
  downloads, // eslint-disable-line @typescript-eslint/no-unused-vars
  rating,
  marketplaceUrl,
  description,
  tags,
  onAdd,
  onClose,
}: Props) {
  useEffect(() => {
    trackAddRecipeDialogOpened(recipeId)
  }, [recipeId])
  const {versions: availableRecipeVersions, isLoading: isRecipeVersionsLoading} =
    useFetchRecipeVersions(recipeId)
  const [isButtonLoaderShown, showButtonLoader, hideButtonLoader] = useBooleanState()
  const [selectedRecipeVersion, setSelectedRecipeVersion] = useState<SelectedVersionItem>()
  const {recipe, isLoading: isRecipeLoading} = useFetchRecipeContent(
    recipeId,
    selectedRecipeVersion?.version ?? LATEST_COMPATIBLE,
  )
  const {yamlEditorRef} = useRecipeEditor(recipe?.content ?? '')
  const {applyRecipe} = useApplyRecipe()

  const versionsSelectData = useMemo(
    () =>
      (availableRecipeVersions?.map(version => ({
        label: version.version,
        compatible: version.compatible,
        key: version.version,
        version: version.version,
        rgItemType: ListItemType.CUSTOM,
        disabled: version.compatible === false,
        template: e => (
          <div
            className={classNames(styles.versionListItem, {[styles.incompatible]: !e.compatible})}
          >
            {e.version}
            <span className={styles.badge}>{'Incompatible'}</span>
          </div>
        ),
      })) ?? emptyArray) as Array<SelectedVersionItem>,
    [availableRecipeVersions],
  )

  const onRecipeVersionSelect = useCallback(
    (e: SelectedVersionItem | null) => {
      if (e) {
        setSelectedRecipeVersion(e)
        trackSelectedVersionChanged(recipeId, e.version)
      }
    },
    [recipeId],
  )

  useEffect(() => {
    if (selectedRecipeVersion || !recipe?.version) {
      return
    }

    setSelectedRecipeVersion({
      version: recipe.version,
      key: recipe.version,
      compatible: recipe.compatible,
      label: recipe.version,
    })
  }, [recipe?.compatible, recipe?.version, selectedRecipeVersion])

  const install = useCallback(() => {
    const initiateInstalling = async () => {
      if (!recipe) {
        return
      }

      showButtonLoader()

      try {
        await applyRecipe({recipeName: recipeId, version: recipe?.version})
      } catch (e) {
        hideButtonLoader()
        return
      }

      if (selectedRecipeVersion?.version) {
        trackRecipeAdded(recipeId, selectedRecipeVersion.version)
      }

      onAdd(recipe?.runTypeId).catch(_ => {
        alert.error(`Could not add recipe ${name}, please try again later`)
        hideButtonLoader()
      })
    }

    initiateInstalling()
  }, [
    recipe,
    showButtonLoader,
    applyRecipe,
    recipeId,
    onAdd,
    name,
    hideButtonLoader,
    selectedRecipeVersion,
  ])

  const descriptionTruncateLength = 300

  return (
    <Dialog
      className={styles.overlay}
      contentClassName={styles.dialog}
      label={`Add ${name}`}
      onCloseAttempt={onClose}
      showCloseButton
      closeButtonInside
      modal={false}
      show
      autoFocusFirst={false}
    >
      <Header>
        <div className={styles.header}>
          <BuildStepSelectorItemIcon
            url={iconUrl}
            alt={name}
            runnerKey={recipeId}
            buildStepType={BuildStepType.PUBLIC_RECIPE}
            size={'header'}
          />
          <div>
            <Text className={styles.title}>{name}</Text>
            <div className={styles.summary}>
              {vendor?.name && (
                <div className={styles.vendor}>
                  <Text size={Text.Size.S} info bold={false}>
                    {`by ${vendor.name}`}
                    {vendor.verified && <Icon glyph={okIcon} className={styles.verified} />}
                  </Text>
                </div>
              )}
              {!!rating && (
                <div className={styles.statistics}>
                  {/* Download counter goes here if we ever decide to add it back */}
                  {!!rating && (
                    <div className={styles.statisticsItem}>
                      <Icon glyph={starEmptyIcon} />
                      <Text size={Text.Size.S} className={styles.statisticsValue}>
                        {rating}
                      </Text>
                    </div>
                  )}
                </div>
              )}
            </div>
          </div>
        </div>
      </Header>
      {!!tags && tags.length > 0 && (
        <div className={styles.container}>
          <RecipeTagList tags={tags} />
        </div>
      )}
      <Content>
        <div>
          <Text className={styles.summary}>
            {truncateWithEllipsis(description, descriptionTruncateLength)}
          </Text>
        </div>
        <div className={styles.codeEditorContainer}>
          <div className={styles.editorHeader}>
            <div>
              {`Version: ${!isRecipeVersionsLoading ? 'v.' : ''}`}
              {isRecipeVersionsLoading ? (
                <LoaderInline />
              ) : (
                <Select
                  type={Type.INLINE}
                  data={versionsSelectData}
                  label={''}
                  buttonClassName={styles.selectButton}
                  selected={selectedRecipeVersion}
                  onOpen={() =>
                    selectedRecipeVersion?.version &&
                    trackVersionListExpanded(recipeId, selectedRecipeVersion.version)
                  }
                  onSelect={onRecipeVersionSelect}
                />
              )}
            </div>
            {recipe?.content ? (
              <CopyIconButton
                title={'Copy code'}
                text={recipe?.content}
                beforeCopyContent={'Copy code'}
                afterCopyContent={'Copied!'}
                onClick={() =>
                  selectedRecipeVersion?.version &&
                  trackCopyButtonClicked(recipeId, selectedRecipeVersion.version)
                }
                wrapperClassName={styles.copy}
              />
            ) : null}
          </div>
          {isRecipeLoading ? <Loader /> : <div ref={yamlEditorRef} />}
        </div>
      </Content>
      <Panel>
        <Button primary loader={isButtonLoaderShown} onClick={install}>
          {`Use version ${selectedRecipeVersion?.version ?? ''}`}
        </Button>
        <Button
          icon={newWindowIcon}
          inline={false}
          href={marketplaceUrl}
          onClick={() =>
            trackPublicRecipeLinkOpened(
              recipeId,
              selectedRecipeVersion?.version,
              RecipeLinkLocation.ADD_RECIPE_DIALOG,
            )
          }
          target={'_blank'}
          rel="noopener, noreferrer"
        >
          {'View at the Marketplace'}
        </Button>
      </Panel>
    </Dialog>
  )
}
