import type {BuildStepList} from '../BuildStepSelector.list'
import type {Slice} from '../BuildStepSelector.slice'
import type {BuildStepItem} from '../BuildStepSelector.types'
import {retainIfEqual} from '../BuildStepSelector.utils'

import {FocusOn, LoaderType} from './BuildStepSelectorList.types'

interface State {
  loadedList: BuildStepList
  loader: LoaderType
  error: string | null
}

enum ActionType {
  SET_LOADED_PAGE = 'SET_LOADED_PAGE',
  SET_LOADER = 'SET_LOADER',
  SET_FOCUS = 'SET_FOCUS',
  SET_ERROR = 'SET_ERROR',
}

interface SetLoadedPageAction {
  type: ActionType.SET_LOADED_PAGE
  page: Slice<BuildStepItem>
}

interface SetLoaderAction {
  type: ActionType.SET_LOADER
  loaderType: LoaderType
}

interface SetFocusAction {
  type: ActionType.SET_FOCUS
  focusOn: FocusOn
}

interface SetErrorAction {
  type: ActionType.SET_ERROR
  error: string | null
}

type Action = SetLoadedPageAction | SetLoaderAction | SetFocusAction | SetErrorAction

function reducer(state: State, action: Action): State {
  switch (action.type) {
    case ActionType.SET_LOADED_PAGE:
      return retainIfEqual(state, {
        ...state,
        loadedList: state.loadedList.setPage(action.page),
        loader: LoaderType.DISABLED,
      })

    case ActionType.SET_LOADER:
      return retainIfEqual(state, {...state, loader: action.loaderType})

    case ActionType.SET_FOCUS:
      switch (action.focusOn) {
        case FocusOn.FIRST:
          state.loadedList.focusOnFirstItem()
          break
        case FocusOn.NEXT:
          state.loadedList.focusOnNextItem()
          break
        case FocusOn.PREV:
          state.loadedList.focusOnPrevItem()
          break
        default:
          if (!state.loadedList.hasFocusedItem) {
            return state // to reduce redundant renders
          }
          state.loadedList.unfocusAllItems()
      }
      return {...state}

    case ActionType.SET_ERROR:
      return retainIfEqual(state, {...state, error: action.error})

    default:
      return state
  }
}

const setLoadedPage = (page: Slice<BuildStepItem>): SetLoadedPageAction => ({
  type: ActionType.SET_LOADED_PAGE,
  page,
})

const setLoader = (loaderType: LoaderType): SetLoaderAction => ({
  type: ActionType.SET_LOADER,
  loaderType,
})

const setFocus = (focusOn: FocusOn): SetFocusAction => ({
  type: ActionType.SET_FOCUS,
  focusOn,
})

const setError = (error: string | null): SetErrorAction => ({
  type: ActionType.SET_ERROR,
  error,
})

export {reducer, setLoadedPage, setLoader, setFocus, setError}
