export function truncateWithEllipsis(str: string, maxLength: number): string {
  if (str == null) {
    return ''
  }

  const ellipsis = '...'
  if (str.length > maxLength) {
    return str.slice(0, maxLength - ellipsis.length) + ellipsis
  }
  return str
}

export const LATEST_COMPATIBLE = 'highest-compatible'
