import Button from '@jetbrains/ring-ui-built/components/button/button'
import Link from '@jetbrains/ring-ui-built/components/link/link'
import LoaderInline from '@jetbrains/ring-ui-built/components/loader-inline/loader-inline'
import {resolveRelative} from '@jetbrains/teamcity-ui/dist/utils'
import classNames from 'classnames'
import type * as React from 'react'

import type {RunnerType} from './SelectBuildRunners.types'

import styles from './SelectBuildRunners.module.css'

function SelectBuildRunnersDescription({
  isLoading,
  onChangeClick,
  selected,
  readOnly,
}: {
  selected: RunnerType | null
  isLoading: boolean
  readOnly: boolean | undefined
  onChangeClick: (event: React.MouseEvent<any>) => void
}) {
  const isMetaRunner = !!selected?.ownerProjectInfo

  if (isLoading) {
    return <LoaderInline />
  }

  return (
    <div className={styles.selectedRunner}>
      <div className={classNames(styles.description, styles.selected)}>
        <span>{selected?.description}</span>
        {!readOnly && (
          <Button inline className={styles.reselectButton} onClick={onChangeClick}>
            {'Change runner'}
          </Button>
        )}
        {isMetaRunner ? (
          <div>
            <span>{'Note: The '}</span>
            <a
              href={resolveRelative(selected.ownerProjectInfo.editRunnerUrl)}
              title="Click to navigate to recipe definition"
            >
              {selected.name}
            </a>
            <span>{` recipe is defined in the `}</span>
            <Link
              href={resolveRelative(
                `/admin/editProject.html?init=1&projectId=${selected.ownerProjectInfo.id}`,
              )}
            >
              {selected.ownerProjectInfo.name}
            </Link>
            <span>{` project.`}</span>
          </div>
        ) : null}
      </div>
    </div>
  )
}

export default SelectBuildRunnersDescription
