import newWindowIcon from '@jetbrains/icons/new-window-12px.svg'
import Icon from '@jetbrains/ring-ui-built/components/icon/icon'
import Link from '@jetbrains/ring-ui-built/components/link/link'

import styles from './OpenNewWindowLink.module.css'

interface Props {
  link: string
  onClick: () => void
}

export default function OpenNewWindowLink({link, onClick}: Props) {
  return (
    <Link
      href={link}
      onClick={e => {
        e.stopPropagation()
        onClick?.()
      }}
      target={'_blank'}
      rel="noreferrer"
      aria-label="Open JetBrains Marketplace in new window"
    >
      <Icon glyph={newWindowIcon} className={styles.icon} />
    </Link>
  )
}
