import Text from '@jetbrains/ring-ui-built/components/text/text'
import {useCallback} from 'react'

import {useDebounceValue} from '../../../hooks/useDebounceValue'
import {restApi} from '../../../services/rest'
import store from '../../../store'
import type {ProjectId} from '../../../types'

import {trackAllRecipesLinkOpened} from './BuildStepSelector.analyticEvents'
import {getMarketplaceRecipesUrl} from './BuildStepSelector.list.publicRecipes.utils'
import {Slice} from './BuildStepSelector.slice'
import type {
  BuildStepItem,
  FocusabilityData,
  PublicRecipeSearchResult,
  Vendor,
} from './BuildStepSelector.types'
import {BuildStepType, FocusDirection} from './BuildStepSelector.types'
import {getInternalProperty} from './BuildStepSelector.utils'
import BuildStepSelectorList from './BuildStepSelectorList/BuildStepSelectorList'
import OpenNewWindowLink from './OpenNewWindowLink/OpenNewWindowLink'

const DEFAULT_PUBLIC_RECIPE_LIST_PAGE_SIZE = 20
const EXTERNAL_SEARCH_DEBOUNCE_DELAY = 300

interface Props {
  projectId: ProjectId
  onActivate: (itemId: string) => Promise<void>
  searchQuery: string
  focused: boolean
  onFocusabilityChange: (type: BuildStepType, focusableList: FocusabilityData) => void
}

export default function PublicRecipeList({
  projectId,
  onActivate,
  searchQuery,
  focused,
  onFocusabilityChange,
}: Props) {
  const externalSearchSignal = useDebounceValue(searchQuery, EXTERNAL_SEARCH_DEBOUNCE_DELAY)
  const marketplaceRecipesUrl = getMarketplaceRecipesUrl()
  const publicRecipeListPageSize = getInternalProperty(
    'teamcity.ui.buildStepSelector.publicRecipeList.pageSize',
    DEFAULT_PUBLIC_RECIPE_LIST_PAGE_SIZE,
  )

  const fetchPublicRecipes: (offset: number, count: number) => Promise<Slice<BuildStepItem>> =
    useCallback(
      async (offset: number, count: number) => {
        const {data: recipeSearchResponse, isError} = await store.dispatch(
          restApi.endpoints.searchPublicRecipes.initiate({
            projectId,
            searchQuery,
            offset,
            limit: count,
          }),
        )
        if (isError) {
          throw new Error('Error fetching public recipes')
        }
        const recipeItems = recipeSearchResponse!.recipes.map(mapRecipeSearchResult)
        return new Slice<BuildStepItem>(recipeItems, offset, recipeSearchResponse!.totalCount)
      },
      [projectId, searchQuery],
    )

  function mapRecipeSearchResult(searchResult: PublicRecipeSearchResult): BuildStepItem {
    return {
      id: searchResult.name,
      type: BuildStepType.PUBLIC_RECIPE,
      name: searchResult.title,
      description: searchResult.description,
      tags: searchResult.tags,
      link: searchResult.link,
      iconUrl: searchResult.icon,
      vendor: searchResult.vendor
        ? ({
            name: searchResult.vendor.name,
            verified: searchResult.vendor.verified,
            link: searchResult.vendor.url,
          } as Vendor)
        : undefined,
      rating: searchResult.rating,
      downloads: searchResult.downloads,
    } as BuildStepItem
  }

  const handleOnItemFocus = useCallback(
    (itemIndex: number, _: boolean) => {
      const allowedDirections: FocusDirection[] = [FocusDirection.LEFT]
      if (itemIndex === 0) {
        allowedDirections.push(FocusDirection.UP)
      }
      onFocusabilityChange(BuildStepType.PUBLIC_RECIPE, {
        isFocusInAllowed: true,
        allowedFocusOutDirections: allowedDirections,
      })
    },
    [onFocusabilityChange],
  )

  const handleLengthChanged = useCallback(
    (length: number) => {
      onFocusabilityChange(BuildStepType.PUBLIC_RECIPE, {
        isFocusInAllowed: length > 0,
        allowedFocusOutDirections: length > 0 ? [FocusDirection.LEFT, FocusDirection.UP] : [],
      })
    },
    [onFocusabilityChange],
  )

  const handlePublicRecipeActivate = useCallback(
    async (recipeRunTypeId: string) => {
      await onActivate(recipeRunTypeId!)
    },
    [onActivate],
  )

  return (
    <BuildStepSelectorList
      title={
        <Text>
          {'Most popular recipes in marketplace'}
          <OpenNewWindowLink link={marketplaceRecipesUrl} onClick={trackAllRecipesLinkOpened} />
        </Text>
      }
      buildStepType={BuildStepType.PUBLIC_RECIPE}
      fetchData={fetchPublicRecipes}
      reloadSignal={externalSearchSignal}
      emptyMessage={'No recipes found'}
      errorMessage={'Could not fetch public recipes, please try again later'}
      pageSize={publicRecipeListPageSize}
      onLengthChanged={handleLengthChanged}
      focused={focused}
      onItemActivate={handlePublicRecipeActivate}
      onItemFocus={handleOnItemFocus}
    />
  )
}
