import type React from 'react'
import {createContext, useContext, useState} from 'react'

interface BuildStepSelectorDialogContextValue {
  isOpen: boolean
  setIsOpen: (value: boolean) => void
}

const BuildStepSelectorDialogContext = createContext<
  BuildStepSelectorDialogContextValue | undefined
>(undefined)

export function BuildStepSelectorDialogProvider({children}: {children: React.ReactNode}) {
  const [isOpen, setIsOpen] = useState(false)

  return (
    <BuildStepSelectorDialogContext.Provider value={{isOpen, setIsOpen}}>
      {children}
    </BuildStepSelectorDialogContext.Provider>
  )
}

export function useBuildStepSelectorDialogContext() {
  return useContext(BuildStepSelectorDialogContext)
}
