import {Slice} from './BuildStepSelector.slice'
import type {BuildStepItem, BuildStepType} from './BuildStepSelector.types'

export class BuildStepList {
  static empty(type: BuildStepType, pageSize: number): BuildStepList {
    return new BuildStepList(type, pageSize, Slice.empty<BuildStepItem>())
  }

  page: number

  private constructor(
    public type: BuildStepType,
    public pageSize: number,
    public items: Slice<BuildStepItem>,
  ) {
    this.type = type
    this.pageSize = pageSize
    this.page = -1
    this.items = items
  }

  get hasBeenLoadedOnce(): boolean {
    return this.page >= 0
  }

  get hasReachedLastPage(): boolean {
    return this.items.offset + this.items.count >= this.items.total
  }

  get isEmpty(): boolean {
    return this.items.count === 0
  }

  get length(): number {
    return this.items.count
  }

  get total(): number {
    return this.items.total
  }

  get focusedItemIndex(): number {
    return this.items.items.findIndex(item => item.focused)
  }

  get hasFocusedItem(): boolean {
    return this.focusedItemIndex !== -1
  }

  get hasFocusedLastItemInPage(): boolean {
    return this.focusedItemIndex === this.items.items.length - 1
  }

  get hasFocusedLastItem(): boolean {
    return this.hasFocusedLastItemInPage && this.hasReachedLastPage
  }

  setPage(page: Slice<BuildStepItem>): BuildStepList {
    return page.isFirst ? this.resetTo(page) : this.addPage(page)
  }

  private resetTo(page: Slice<BuildStepItem>): BuildStepList {
    const hadFocusedItem = this.hasFocusedItem
    this.items = page
    this.page = 0
    if (hadFocusedItem) {
      this.focusOnFirstItem()
    }
    return this
  }

  private addPage(page: Slice<BuildStepItem>): BuildStepList {
    this.items = this.items.concat(page)
    this.page++
    return this
  }

  focusOnFirstItem() {
    this.focusOnItemByIndex(0)
  }

  focusOnPrevItem() {
    this.focusOnItemByIndex(this.focusedItemIndex - 1)
  }

  focusOnNextItem() {
    this.focusOnItemByIndex(this.focusedItemIndex + 1)
  }

  unfocusAllItems() {
    this.items.items.forEach(item => (item.focused = false))
  }

  mapToArrayOf<TResult>(
    callback: (item: BuildStepItem, index: number, array: BuildStepItem[]) => TResult,
  ): TResult[] {
    return this.items.items.map(callback)
  }

  private focusOnItemByIndex(index: number) {
    if (index < 0 || index >= this.items.items.length) {
      return
    }
    if (this.focusedItemIndex === index) {
      return
    }
    this.unfocusAllItems()
    this.items.items[index].focused = true
  }
}
