import isEqual from 'lodash/isEqual'

import type {InternalProps} from '../../../types/BS_types'

export const retainIfEqual = <T>(oldState: T, newState: T): T =>
  isEqual(oldState, newState) ? oldState : newState

export const getInternalProperty = <K extends keyof InternalProps>(
  name: K,
  defaultValue: InternalProps[K],
): InternalProps[K] => window.internalProps[name] ?? defaultValue
