import okIcon from '@jetbrains/icons/ok-12px.svg'
import starEmptyIcon from '@jetbrains/icons/star-empty-12px.svg'
import Icon from '@jetbrains/ring-ui-built/components/icon/icon'
import Text from '@jetbrains/ring-ui-built/components/text/text'
import classNames from 'classnames'
import {memo, useCallback, useEffect} from 'react'

import AddPublicRecipeDialog from '../AddPublicRecipeDialog/AddPublicRecipeDialog'
import {useAddPublicRecipeDialog} from '../AddPublicRecipeDialog/AddPublicRecipeDialog.hooks'
import {trackPublicRecipeLinkOpened, RecipeLinkLocation} from '../BuildStepSelector.analyticEvents'
import {useBuildStepSelectorDialogContext} from '../BuildStepSelector.context'
import type {Deprecation, Vendor} from '../BuildStepSelector.types'
import {BuildStepType} from '../BuildStepSelector.types'
import BuildStepSelectorItemIcon from '../BuildStepSelectorItemIcon/BuildStepSelectorItemIcon'
import OpenNewWindowLink from '../OpenNewWindowLink/OpenNewWindowLink'

import {normalizeProjectName} from './BuildStepSelectorItem.utils'

import styles from './BuildStepSelectorItem.module.css'

interface Props {
  id: string
  type: BuildStepType
  name: string
  description: string
  deprecation?: Deprecation
  owningProject?: string
  link?: string
  vendor?: Vendor
  iconUrl?: string
  downloads?: number
  rating?: number
  tags?: string[]
  focused: boolean
  activate?: (itemId: string) => Promise<void>
}

function BuildStepSelectorItem({
  id,
  type,
  name,
  description,
  deprecation,
  owningProject,
  link,
  vendor,
  iconUrl,
  downloads,
  rating,
  tags,
  focused,
  activate,
}: Props) {
  const addRecipeDialog = useAddPublicRecipeDialog()
  const dialogContext = useBuildStepSelectorDialogContext()

  const memoizedActivate = useCallback(async () => {
    if (type === BuildStepType.PUBLIC_RECIPE) {
      addRecipeDialog.onShow()
      dialogContext?.setIsOpen(true)
    } else if (activate) {
      await activate(id)
    } else {
      throw new Error('activate callback is required')
    }
  }, [type, activate, addRecipeDialog, dialogContext, id])

  const onClosePublicRecipesDialog = useCallback(() => {
    dialogContext?.setIsOpen(false)
    addRecipeDialog.onClose()
  }, [addRecipeDialog, dialogContext])

  useEffect(() => {
    const handleKeyDown = (event: KeyboardEvent) => {
      if (!focused) {
        return
      }
      switch (event.key) {
        case 'Enter':
          event.preventDefault()
          memoizedActivate()
          break
        default:
          break
      }
    }

    window.addEventListener('keydown', handleKeyDown)
    return () => {
      window.removeEventListener('keydown', handleKeyDown)
    }
  }, [memoizedActivate, focused, addRecipeDialog])

  return (
    <>
      {addRecipeDialog.visible && activate && (
        <AddPublicRecipeDialog
          recipeId={id}
          name={name}
          vendor={vendor}
          iconUrl={iconUrl}
          downloads={downloads}
          rating={rating}
          marketplaceUrl={link!}
          description={description}
          tags={tags}
          onAdd={activate}
          onClose={onClosePublicRecipesDialog}
        />
      )}
      <div
        key={id}
        className={classNames(styles.item, {[styles.focused]: focused})}
        role="presentation"
        onClick={memoizedActivate}
        data-test={`build-step-selector-item ${type.toLowerCase()}`}
      >
        <div className={styles.icon}>
          <BuildStepSelectorItemIcon
            url={iconUrl}
            alt={name}
            runnerKey={id}
            buildStepType={type}
            deprecated={!!deprecation}
          />
        </div>

        <div className={styles.info}>
          <div className={styles.summary}>
            <div>
              <Text size={Text.Size.M} className={classNames({[styles.deprecated]: deprecation})}>
                {name + (deprecation ? ' (deprecated)' : '')}
              </Text>
              {type === BuildStepType.PUBLIC_RECIPE && link && (
                <OpenNewWindowLink
                  link={link}
                  onClick={() =>
                    trackPublicRecipeLinkOpened(
                      id,
                      undefined,
                      RecipeLinkLocation.ADD_BUILD_STEP_PAGE,
                    )
                  }
                />
              )}
              {type === BuildStepType.PUBLIC_RECIPE && vendor?.name && (
                <Text size={Text.Size.S} className={styles.vendor}>
                  {vendor.name}
                  {vendor.verified && <Icon glyph={okIcon} className={styles.verified} />}
                </Text>
              )}
              {type === BuildStepType.PRIVATE_RECIPE && owningProject && (
                <Text size={Text.Size.S} className={styles.owningProject}>
                  {normalizeProjectName(owningProject)}
                </Text>
              )}
            </div>
            {!!rating && (
              <div className={styles.statistics}>
                {/* Download counter goes here if we ever decide to add it back */}
                {!!rating && (
                  <div className={styles.statisticsItem}>
                    <Icon glyph={starEmptyIcon} />
                    <Text size={Text.Size.S} className={styles.statisticsValue}>
                      {rating}
                    </Text>
                  </div>
                )}
              </div>
            )}
          </div>
          <div>
            <Text size={Text.Size.S} className={styles.description}>
              {description}
            </Text>
          </div>
        </div>
      </div>
    </>
  )
}

export default memo(BuildStepSelectorItem)
