class TrieNode<T> {
  children = new Map<string, TrieNode<T>>()
  values: Array<{value: T; insertOrder: number}> = []
}

export interface TrieOptions {
  field: string // name of field in the object
  tokenize: boolean // split the field value (string, or array of strings) into tokens by whitespace
  tokenizeCamelCase?: boolean // split "camelCase" entries as "camel" and "case"
}

export class Trie<T> {
  private root: TrieNode<T> = new TrieNode<T>()
  private options: TrieOptions[]
  private insertCounter = 0
  private cyrillicToLatinMap: Record<string, string> = {
    // eslint-disable-next-line prettier/prettier
    'й': 'q', 'ц': 'w', 'у': 'e', 'к': 'r', 'е': 't', 'н': 'y', 'г': 'u', 'ш': 'i', 'щ': 'o', 'з': 'p', 'х': '[', 'ъ': ']',
    // eslint-disable-next-line prettier/prettier
    'ф': 'a', 'ы': 's', 'в': 'd', 'а': 'f', 'п': 'g', 'р': 'h', 'о': 'j', 'л': 'k', 'д': 'l', 'ж': ';', 'э': '\'',
    // eslint-disable-next-line prettier/prettier
    'я': 'z', 'ч': 'x', 'с': 'c', 'м': 'v', 'и': 'b', 'т': 'n', 'ь': 'm', 'б': ',', 'ю': '.', '.': '/'
  }

  constructor(indexOptions: TrieOptions[]) {
    this.options = indexOptions
  }

  private convertToLatin = (input: string): string =>
    input
      .split('')
      .map(char => this.cyrillicToLatinMap[char] || char)
      .join('')

  get isEmpty(): boolean {
    return this.root.children.size === 0 && this.root.values.length === 0
  }

  insert(obj: T): void {
    const insertOrder = this.insertCounter++
    this.options.forEach(option => {
      const value = obj[option.field as keyof T]

      const processValue = (val: string) => {
        let tokens: string[] = [this.sanitize(val)]

        if (option.tokenize) {
          tokens = tokens.flatMap(token => this.tokenize(token))
        }

        if (option.tokenizeCamelCase) {
          tokens = tokens.flatMap(token => [token, ...this.tokenizeCamelCase(token)])
        }

        for (const [i, token] of tokens.entries()) {
          tokens[i] = token.toLowerCase()
        }

        // remove potential duplicates and empty values
        ;[...new Set(tokens)]
          .filter(Boolean)
          .forEach(token => this.insertKey(token, obj, insertOrder))
      }

      if (typeof value === 'string') {
        processValue(value)
      } else if (Array.isArray(value)) {
        value.filter((v): v is string => typeof v === 'string').forEach(processValue)
      }
    })
  }

  search(prefix: string): T[] {
    const sanitizedPrefix = this.sanitize(prefix).toLowerCase()
    const isCyrillic = /[а-яА-ЯЁё]/.test(sanitizedPrefix)
    const latinPrefix = isCyrillic ? this.convertToLatin(sanitizedPrefix) : sanitizedPrefix
    const node = this.findNode(latinPrefix)
    if (!node) {
      return []
    }

    const results: Array<{value: T; insertOrder: number}> = []
    this.collectValues(node, results)
    return Array.from(
      new Set(results.sort((a, b) => a.insertOrder - b.insertOrder).map(item => item.value)),
    )
  }

  filter(predicate: (value: T) => boolean): T[] {
    const results: Array<{value: T; insertOrder: number}> = []
    this.filterRecursive(this.root, predicate, results)
    return results.sort((a, b) => a.insertOrder - b.insertOrder).map(item => item.value)
  }

  private filterRecursive(
    node: TrieNode<T>,
    predicate: (value: T) => boolean,
    results: Array<{value: T; insertOrder: number}>,
  ): void {
    node.values.forEach(item => {
      if (predicate(item.value) && !results.some(r => r.value === item.value)) {
        results.push(item)
      }
    })

    node.children.forEach(child => {
      this.filterRecursive(child, predicate, results)
    })
  }

  private tokenize(value: string): string[] {
    return value.split(/\s+/).map(v => this.sanitize(v))
  }

  private tokenizeCamelCase(word: string): string[] {
    const tokens = word
      // processing sequences of capital letters (XML, JS, etc)
      .replace(/([A-Z]{1,})(?=[A-Z][a-z]|\s|$)/g, ' $1 ')
      // split camelCase patterns
      .replace(/([a-z])([A-Z])/g, '$1 $2')
      // special case: a single capital letter at the beginning of a word
      .replace(/^([A-Z])([a-z])/g, '$1 $2')
      .split(' ')
      .filter(Boolean)

    // additionally, split tokens that contain numbers
    const allTokens = tokens.flatMap(token => {
      // if the token contains numbers, we add both the whole token and its parts
      if (/\d/.test(token)) {
        const parts = token.match(/[a-z]+|\d+/gi) || []
        return [token, ...parts]
      }
      return [token]
    })

    return [...new Set(allTokens)].map(token => this.sanitize(token)).filter(Boolean)
  }

  private sanitize(value: string): string {
    return value.replace(/[^a-zа-яё0-9\s]/gi, ' ').trim()
  }

  private insertKey(key: string, obj: T, insertOrder: number): void {
    let node = this.root
    let i = 0

    while (i < key.length) {
      let child = node.children.get(key[i])

      if (!child) {
        child = new TrieNode<T>()
        node.children.set(key[i], child)
      }

      node = child
      i++
    }

    if (!node.values.some(v => v.value === obj)) {
      node.values.push({value: obj, insertOrder})
    }
  }

  private findNode(prefix: string): TrieNode<T> | null {
    let node = this.root
    for (const char of prefix) {
      const child = node.children.get(char)
      if (!child) {
        return null
      }
      node = child
    }
    return node
  }

  private collectValues(node: TrieNode<T>, results: Array<{value: T; insertOrder: number}>): void {
    results.push(...node.values)

    for (const child of node.children.values()) {
      this.collectValues(child, results)
    }
  }
}
