import {useCallback, useMemo} from 'react'

import type {Slice} from './BuildStepSelector.slice'
import type {
  BuildStepItem,
  BuildStepItemsFetcher,
  FocusabilityData,
} from './BuildStepSelector.types'
import {FocusDirection, BuildStepType} from './BuildStepSelector.types'
import BuildStepSelectorList from './BuildStepSelectorList/BuildStepSelectorList'

interface Props {
  fetcher: BuildStepItemsFetcher
  onActivate: (itemId: string) => Promise<void>
  searchQuery: string
  focused: boolean
  onReload: () => void
  onFocusabilityChange: (type: BuildStepType, focusableList: FocusabilityData) => void
}

export default function RunnerList({
  fetcher,
  onActivate,
  searchQuery,
  focused,
  onReload,
  onFocusabilityChange,
}: Props) {
  const runnersListPageSize = useMemo(
    // calc runners list page size as a number of non-deprecated runners
    () => fetcher.countOf(i => i.type === BuildStepType.RUNNER && !i.deprecation),
    [fetcher],
  )

  const fetchRunners: (offset: number, count: number) => Promise<Slice<BuildStepItem>> =
    useCallback(
      (offset: number, count: number) =>
        fetcher.fetch(searchQuery, BuildStepType.RUNNER, offset, count),
      [fetcher, searchQuery],
    )

  const handleOnItemFocus = useCallback(
    (_: number, __: boolean) => {
      onFocusabilityChange(BuildStepType.RUNNER, {
        isFocusInAllowed: true,
        allowedFocusOutDirections: [FocusDirection.RIGHT],
      })
    },
    [onFocusabilityChange],
  )

  const handleOnReload = useCallback(onReload, [onReload])

  const handleLengthChanged = useCallback(
    (length: number) => {
      onFocusabilityChange(BuildStepType.RUNNER, {
        isFocusInAllowed: length > 0,
        allowedFocusOutDirections: length > 0 ? [FocusDirection.RIGHT] : [],
      })
    },
    [onFocusabilityChange],
  )

  return (
    <BuildStepSelectorList
      buildStepType={BuildStepType.RUNNER}
      fetchData={fetchRunners}
      reloadSignal={searchQuery}
      emptyMessage={'No runners found'}
      errorMessage={'Could not retrieve runners'}
      pageSize={runnersListPageSize}
      onReload={handleOnReload}
      onLengthChanged={handleLengthChanged}
      focused={focused}
      onItemActivate={onActivate}
      onItemFocus={handleOnItemFocus}
    />
  )
}
