import {useState, useCallback} from 'react'

type AddRecipeDialog = {
  onClose: () => void
  onShow: () => void
  visible: boolean
}
export function useAddPublicRecipeDialog(): AddRecipeDialog {
  const [visible, setShow] = useState(false)

  const onClose = useCallback(() => {
    setShow(false)
  }, [setShow])

  const onShow = useCallback(() => {
    setShow(true)
  }, [setShow])

  return {
    onShow,
    visible,
    onClose,
  }
}
