import isEqual from 'lodash/isEqual'

import type {FocusabilityData} from './BuildStepSelector.types'
import {BuildStepType, FocusDirection} from './BuildStepSelector.types'

interface State {
  searchQuery: string
  focusabilityData: Record<BuildStepType, FocusabilityData>
  focused?: BuildStepType
}

enum ActionType {
  SEARCH = 'SEARCH',
  FOCUS = 'FOCUS',
  FOCUSABILITY_CHANGE = 'FOCUSABILITY_CHANGE',
}

interface SearchAction {
  type: ActionType.SEARCH
  query: string
}

interface FocusAction {
  type: ActionType.FOCUS
  direction: FocusDirection
  onSuccess: () => void
}

interface ChangeFocusabilityAction {
  type: ActionType.FOCUSABILITY_CHANGE
  focusableType: BuildStepType
  focusabilityData: FocusabilityData
}

type Action = SearchAction | FocusAction | ChangeFocusabilityAction

const focusabilityMap: Record<BuildStepType, FocusDirection[]> = {
  [BuildStepType.RUNNER]: [FocusDirection.RIGHT],
  [BuildStepType.PRIVATE_RECIPE]: [FocusDirection.DOWN, FocusDirection.LEFT],
  [BuildStepType.PUBLIC_RECIPE]: [FocusDirection.UP, FocusDirection.LEFT],
}

const interfaceStructure: (BuildStepType | undefined)[][] = [
  [BuildStepType.RUNNER, BuildStepType.PRIVATE_RECIPE],
  [BuildStepType.RUNNER, BuildStepType.PUBLIC_RECIPE],
]

const directions: [FocusDirection, number, number][] = [
  [FocusDirection.RIGHT, 0, 1],
  [FocusDirection.LEFT, 0, -1],
  [FocusDirection.DOWN, 1, 0],
  [FocusDirection.UP, -1, 0],
]

function refocus(state: State, action: FocusAction): State {
  const {direction, onSuccess} = action
  const {focused: currentFocus, focusabilityData} = state

  const unfocus = (): State => {
    onSuccess()
    return {...state, focused: undefined}
  }

  const findFirstFocusable = (): BuildStepType | undefined =>
    Object.entries(focusabilityData).find(([_, focusable]) => focusable.isFocusInAllowed)?.[0] as
      | BuildStepType
      | undefined

  const canRefocus = (focus: BuildStepType): boolean =>
    focusabilityMap[focus].includes(direction) &&
    focusabilityData[focus].allowedFocusOutDirections.includes(direction)

  const findPosition = (stepType: BuildStepType): [number, number][] =>
    interfaceStructure
      .flatMap((row, i) =>
        row.map((cell, j) => (cell === stepType ? ([i, j] as [number, number]) : undefined)),
      )
      .filter((pos): pos is [number, number] => pos !== undefined)

  const getDirectionBetween = (
    from: BuildStepType,
    to: BuildStepType,
  ): FocusDirection | undefined => {
    const fromPositions = findPosition(from)
    const toPositions = findPosition(to)

    if (fromPositions.length === 0 || toPositions.length === 0) {
      return undefined
    }

    for (const [fromRow, fromCol] of fromPositions) {
      for (const [toRow, toCol] of toPositions) {
        const dir = directions.find(
          ([_, dRow, dCol]) => toRow - fromRow === dRow && toCol - fromCol === dCol,
        )?.[0]
        if (dir) {
          return dir
        }
      }
    }

    return undefined
  }

  const findNextFocus = (current: BuildStepType): BuildStepType | undefined => {
    const allowedDirections = focusabilityMap[current]

    if (!allowedDirections.includes(direction)) {
      return undefined
    }

    return Object.entries(focusabilityData).find(
      ([stepType, focusable]) =>
        stepType !== current &&
        focusable.isFocusInAllowed &&
        getDirectionBetween(current, stepType as BuildStepType) === direction,
    )?.[0] as BuildStepType | undefined
  }

  const applyFocus = (newFocus: BuildStepType): State => {
    onSuccess()
    return {...state, focused: newFocus}
  }

  if (direction === FocusDirection.UNFOCUS) {
    return unfocus()
  }

  if (currentFocus === undefined) {
    const firstFocusable = findFirstFocusable()
    return firstFocusable ? applyFocus(firstFocusable) : state
  }

  if (!canRefocus(currentFocus)) {
    return state
  }

  const nextFocus = findNextFocus(currentFocus)

  return nextFocus ? applyFocus(nextFocus) : state
}

const initialState: State = {
  searchQuery: '',
  focusabilityData: {
    [BuildStepType.RUNNER]: {isFocusInAllowed: false, allowedFocusOutDirections: []},
    [BuildStepType.PRIVATE_RECIPE]: {isFocusInAllowed: false, allowedFocusOutDirections: []},
    [BuildStepType.PUBLIC_RECIPE]: {isFocusInAllowed: false, allowedFocusOutDirections: []},
  },
  focused: undefined,
}

function reducer(state: State, action: Action): State {
  switch (action.type) {
    case ActionType.SEARCH:
      return isEqual(state.searchQuery, action.query)
        ? state
        : {...state, searchQuery: action.query, focused: undefined}

    case ActionType.FOCUS:
      return refocus(state, action)

    case ActionType.FOCUSABILITY_CHANGE:
      const prev = state.focusabilityData[action.focusableType]
      const curr = action.focusabilityData
      if (isEqual(prev, curr)) {
        return state
      }
      state.focusabilityData[action.focusableType] = curr
      return state

    default:
      return state
  }
}

const search = (query: string): SearchAction => ({
  type: ActionType.SEARCH,
  query,
})

const focus = (direction: FocusDirection, onSuccess: () => void = () => {}): FocusAction => ({
  type: ActionType.FOCUS,
  direction,
  onSuccess,
})

const updateFocusability = (
  focusableType: BuildStepType,
  focusableList: FocusabilityData,
): ChangeFocusabilityAction => ({
  type: ActionType.FOCUSABILITY_CHANGE,
  focusableType,
  focusabilityData: focusableList,
})

export {reducer, initialState, search, focus, updateFocusability}
