import searchIcon from '@jetbrains/icons/search.svg'
import type {
  ContainerProps,
  InputSpecificProps,
} from '@jetbrains/ring-ui-built/components/input/input'
import Input from '@jetbrains/ring-ui-built/components/input/input'
import classNames from 'classnames'
import {useEffect, useRef, useCallback, useState} from 'react'

import {useDebounceValue} from '../../../../hooks/useDebounceValue'

import styles from './BuildStepSearchBar.module.css'

type Props = ContainerProps<InputSpecificProps> & {
  className?: string
  placeholder?: string
  onSearchChange: (query: string) => void
}

const DEFAULT_DEBOUNCE_DELAY = 50

export default function BuildStepSearchBar({
  className,
  size,
  placeholder,
  onSearchChange,
  ...restProps
}: Props) {
  const inputRef = useRef<HTMLInputElement>(null)

  const setFocus = useCallback(() => {
    if (inputRef.current) {
      inputRef.current.focus()
    }
  }, [])

  useEffect(() => {
    setFocus()

    // capture any typing on the component to automatically focus the search bar
    const handleKeyDown = (event: KeyboardEvent) => {
      // ignore key presses if the focus is on an input or textarea
      if (
        document.activeElement instanceof HTMLInputElement ||
        document.activeElement instanceof HTMLTextAreaElement
      ) {
        return
      }

      // ignore key presses if the focus is already on an input or if a modifier key is pressed
      if (
        document.activeElement === inputRef.current ||
        event.ctrlKey ||
        event.altKey ||
        event.metaKey
      ) {
        return
      }

      // ignore special keys
      if (event.key.length > 1 && event.key !== 'Backspace') {
        return
      }

      setFocus() // if a user start typing focus input
    }

    window.addEventListener('keydown', handleKeyDown)
    return () => window.removeEventListener('keydown', handleKeyDown)
  }, [setFocus])

  const [searchQuery, setSearchQuery] = useState('')
  const debouncedSearchQuery = useDebounceValue(searchQuery, DEFAULT_DEBOUNCE_DELAY)

  useEffect(() => {
    onSearchChange(debouncedSearchQuery)
  }, [debouncedSearchQuery, onSearchChange])

  const handleChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    setSearchQuery(event.target.value)
  }

  return (
    <Input
      className={classNames(styles.input, className)}
      size={size}
      icon={searchIcon}
      type="search"
      placeholder={placeholder}
      inputRef={inputRef}
      onChange={handleChange}
      {...restProps}
    />
  )
}
