import classNames from 'classnames'
import {memo, useState} from 'react'

import {BuildStepType} from '../BuildStepSelector.types'

import styles from './BuildStepSelectorItemIcon.module.css'

interface Props {
  url?: string
  alt: string
  runnerKey: string
  buildStepType: BuildStepType
  deprecated?: boolean
  size?: 'standard' | 'header'
}

interface Placeholder {
  state: 'placeholder'
  color: string
}

interface Icon {
  state: 'icon'
  url: string
  alt: string
}

type State = Icon | Placeholder

const placehodler = {
  [BuildStepType.RUNNER]: styles.green,
  [BuildStepType.PRIVATE_RECIPE]: styles.violet,
  [BuildStepType.PUBLIC_RECIPE]: styles.orange,
}

function BuildStepSelectorItemIcon({
  url,
  alt,
  runnerKey,
  buildStepType,
  deprecated = false,
  size = 'standard',
}: Props) {
  const [state, setState] = useState<State>(
    url
      ? ({state: 'icon', url, alt} as Icon)
      : ({state: 'placeholder', color: placehodler[buildStepType]} as Placeholder),
  )
  const handleOnIconError = () => {
    setState({state: 'placeholder', color: placehodler[buildStepType]} as Placeholder)
  }

  const sizeClass = size === 'standard' ? styles.standard : styles.header

  switch (state.state) {
    case 'icon':
      return (
        <img
          src={state.url}
          alt={state.alt}
          className={classNames(styles.icon, sizeClass, {[styles.deprecated]: deprecated})}
          data-key={runnerKey}
          onError={handleOnIconError}
        />
      )
    default:
      return (
        <div
          className={classNames(styles.placeholder, state.color, sizeClass, {
            [styles.deprecated]: deprecated,
          })}
          title={alt}
        />
      )
  }
}

export default memo(BuildStepSelectorItemIcon)
