import {getInternalProperty} from './BuildStepSelector.utils'

const DEFAULT_MARKETPLACE_BASE_URL = 'https://plugins.jetbrains.com'

export function getMarketplaceRecipesUrl(): string {
  const marketplaceBaseUrl = getInternalProperty(
    'teamcity.recipes.public.marketplace.url',
    DEFAULT_MARKETPLACE_BASE_URL,
  )
  const normalizedBase = marketplaceBaseUrl.replace(/\/+$/, '')
  const recipeSection = 'teamcity_recipe'
  return `${normalizedBase}/${recipeSection}`
}
