import Button from '@jetbrains/ring-ui-built/components/button/button'
import Link from '@jetbrains/ring-ui-built/components/link/link'

import styles from './AddPrivateRecipeButton.module.css'

interface Props {
  link: string
  inText?: boolean
}

const NAME = 'Add recipe'

export default function AddPrivateRecipeButton(props: Props) {
  return props.inText ? (
    <Link href={props.link}>{NAME}</Link>
  ) : (
    <Button inline className={styles.button} href={props.link} target={'_blank'} rel="noreferrer">
      {NAME}
    </Button>
  )
}
