import {restApi} from '../../../../../services/rest'

export function useFetchRecipeVersions(recipeName: string) {
  const {data, isError, isLoading, isSuccess} = restApi.endpoints.getPublicRecipeVersions.useQuery({
    recipeName,
  })

  return {
    versions: data,
    isError,
    isLoading,
    isSuccess,
  }
}

export function useFetchRecipeContent(recipeName: string, version: string) {
  const {data, isError, isLoading, isSuccess} = restApi.endpoints.getPublicRecipeContent.useQuery({
    recipeName,
    version,
  })

  return {
    recipe: data,
    isError,
    isLoading,
    isSuccess,
  }
}

export function useApplyRecipe() {
  const [applyRecipe] = restApi.endpoints.downloadAndApplyRecipe.useMutation()

  return {
    applyRecipe,
  }
}
