import Text from '@jetbrains/ring-ui-built/components/text/text'
import {resolveRelative} from '@jetbrains/teamcity-ui/dist/utils'
import {useCallback} from 'react'

import AddPrivateRecipeButton from './AddPrivateRecipeButton/AddPrivateRecipeButton'
import type {Slice} from './BuildStepSelector.slice'
import type {
  BuildStepItem,
  BuildStepItemsFetcher,
  FocusabilityData,
} from './BuildStepSelector.types'
import {FocusDirection, BuildStepType} from './BuildStepSelector.types'
import {getInternalProperty} from './BuildStepSelector.utils'
import BuildStepSelectorList from './BuildStepSelectorList/BuildStepSelectorList'

import styles from './BuildStepSelector.module.css'

const DEFAULT_PRIVATE_RECIPE_LIST_PAGE_SIZE = 20

interface Props {
  projectId: string
  fetcher: BuildStepItemsFetcher
  onActivate: (itemId: string) => Promise<void>
  searchQuery: string
  focused: boolean
  onFocusabilityChange: (type: BuildStepType, focusableList: FocusabilityData) => void
}

export default function PrivateRecipeList({
  projectId,
  fetcher,
  onActivate,
  searchQuery,
  focused,
  onFocusabilityChange,
}: Props) {
  const privateRecipeListPageSize = getInternalProperty(
    'teamcity.ui.buildStepSelector.privateRecipeList.pageSize',
    DEFAULT_PRIVATE_RECIPE_LIST_PAGE_SIZE,
  )

  const getProjectRecipesPageUrl = useCallback(
    (id: string) => resolveRelative('/admin/editProject.html', {projectId: id, tab: 'recipe'}),
    [],
  )

  const fetchPrivateRecipes: (offset: number, count: number) => Promise<Slice<BuildStepItem>> =
    useCallback(
      (offset: number, count: number) =>
        fetcher.fetch(searchQuery, BuildStepType.PRIVATE_RECIPE, offset, count),
      [fetcher, searchQuery],
    )

  const handleOnItemFocus = useCallback(
    (_: number, isVeryLastItem: boolean) => {
      const allowedDirections: FocusDirection[] = [FocusDirection.LEFT]
      if (isVeryLastItem) {
        allowedDirections.push(FocusDirection.DOWN)
      }
      onFocusabilityChange(BuildStepType.PRIVATE_RECIPE, {
        isFocusInAllowed: true,
        allowedFocusOutDirections: allowedDirections,
      })
    },
    [onFocusabilityChange],
  )

  const handleLengthChanged = useCallback(
    (length: number) => {
      onFocusabilityChange(BuildStepType.PRIVATE_RECIPE, {
        isFocusInAllowed: length > 0,
        allowedFocusOutDirections: length > 0 ? [FocusDirection.LEFT] : [],
      })
    },
    [onFocusabilityChange],
  )

  return (
    <BuildStepSelectorList
      title={
        <Text>
          {'Your recipes'}
          <AddPrivateRecipeButton link={getProjectRecipesPageUrl(projectId)} />
        </Text>
      }
      buildStepType={BuildStepType.PRIVATE_RECIPE}
      fetchData={fetchPrivateRecipes}
      pageSize={privateRecipeListPageSize}
      onLengthChanged={handleLengthChanged}
      reloadSignal={searchQuery}
      emptyMessage={'No recipes found'}
      errorMessage={'Could not retrieve recipes'}
      initialEmptyMessage={
        <div className={styles.noPrivateRecipesMessage}>
          <Text info>
            {'You have no local recipes. '}
            <AddPrivateRecipeButton inText link={getProjectRecipesPageUrl(projectId)} />
          </Text>
        </div>
      }
      focused={focused}
      onItemActivate={onActivate}
      onItemFocus={handleOnItemFocus}
    />
  )
}
