export class Slice<TItem extends {id: string}> {
  static empty<TItem extends {id: string}>(): Slice<TItem> {
    return new Slice<TItem>([], 0, 0)
  }

  constructor(
    public items: TItem[],
    public offset: number,
    public total: number,
  ) {
    this.items = items
    this.offset = offset
    this.total = total
  }

  get count(): number {
    return this.items.length
  }

  get isFirst(): boolean {
    return this.offset === 0
  }

  concat(other: Slice<TItem>): Slice<TItem> {
    const mergedItems = [...this.items, ...other.items].reduce<TItem[]>(
      (acc, item) => (acc.some(existingItem => existingItem.id === item.id) ? acc : [...acc, item]),
      [],
    )

    return new Slice(mergedItems, this.offset, other.total)
  }

  map<TResult extends {id: string}>(
    callback: (item: TItem, index: number, array: TItem[]) => TResult,
  ): Slice<TResult> {
    const mappedItems = this.items.map(callback)
    return new Slice<TResult>(mappedItems, this.offset, this.total)
  }
}
